pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that are "orphans" (too small to fit typical future items)
    // We define an orphan as a residual < 20. If we have a next_item, we punish residuals that cannot fit it.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 30.0;
        }
    }

    // 2. Bin Consolidation: If this is the only bin that fits the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 3. New Bin Thresholding: Discourage opening new bins unless the fit is near-perfect (waste < 5).
    if bin_residual == bin_capacity {
        if post_residual > 5 {
            score += 60.0;
        }
        // Penalize opening a new bin if open_bins_count is already high
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Lookahead Alignment: If the post_residual can perfectly accommodate the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits (near zero waste after next item)
        score -= (10.0 / (diff + 1.0));
    }

    // 5. Global Load Balancing: Avoid creating bins with extremely low residuals if mean_residual is high
    if mean_residual > 20.0 && post_residual < 10 {
        score += 15.0;
    }

    // 6. Progressive tightening: As we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core objective: Minimize post_residual (Best Fit)
    let mut score = post_residual as f64;

    if is_new_bin {
        // Dynamic threshold for opening a new bin:
        // Increase penalty late-stream to force consolidation.
        // Penalty scaled by fitting_bins_count to discourage new bins when existing ones suffice.
        let consolidation_factor = 0.972 + (progress * 0.08) + (open_bins_count as f64 * 0.005);
        score += (bin_capacity as f64) * consolidation_factor;

        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).sqrt();
        }
    } else {
        // Non-linear penalty for larger residuals to prioritize small gaps
        // Increased power to enforce tighter packing
        score += (post_residual as f64).powf(1.82);

        // Lookahead: reward bins that can accommodate the next item.
        // Dynamically shift weight to favor future-proofing as the stream progresses.
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_weight = 4.2 - (progress * 1.5);
            score -= (next_item_size as f64) * lookahead_weight;
        }

        // Adaptive Fitting Pressure: 
        // If this is the only bin that can take this item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 64.0;
        }

        // Variance control: Penalize deviation from mean_residual to keep bin states uniform.
        // We now penalize bins that are significantly emptier than the global average.
        let deviation = post_residual as f64 - mean_residual;
        if deviation > 0.0 {
            score += deviation * 1.25;
        } else {
            score += deviation.abs() * 0.45;
        }
    }

    // Global pressure: If we have too many bins open, increase penalty for all existing bins 
    // to encourage fuller capacity usage per bin.
    // Use an exponential scaling to penalize bin proliferation aggressively.
    if open_bins_count > 5 {
        score += (open_bins_count as f64).powf(1.45) * 0.35;
    } else {
        score += (open_bins_count as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tightest fit (Best-Fit)
    let mut score = post_residual as f64;

    if is_new_bin {
        // Dynamic threshold for opening a new bin:
        // Increase penalty as we progress to force consolidation.
        // Cap the penalty to avoid excessive fragmentation early on.
        score += (bin_capacity as f64) * 0.85 + (progress * 40.0);

        // If we have many open bins, opening another is costly
        score += (open_bins_count as f64) * 0.5;
    } else {
        // Non-linear penalty for larger residuals to prioritize small gaps
        score += (post_residual as f64).powf(1.65);

        // Lookahead: reward bins that can accommodate the next item.
        // Use a weight that scales inversely with progress to prioritize 
        // future-proofing early in the stream.
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_weight = 2.8 - (progress * 0.5);
            score -= (next_item_size as f64) * lookahead_weight;
        }

        // Adaptive Fitting Pressure: 
        // If this is the only bin that can take this item, make it highly attractive.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }

        // Variance control: Penalize deviation from mean_residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.75;
    }

    // Global pressure: If we have too many bins open, slightly penalize all existing bins 
    // to encourage fuller capacity usage per bin.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    let mut score = post_residual as f64;

    if is_new_bin {
        // Refined opening logic: discourage new bins as progress increases,
        // but allow flexibility if open_bins_count is low to maximize density.
        let base_penalty = (bin_capacity as f64) * 0.982;
        let progress_ramp = progress * 85.0;
        let density_incentive = (open_bins_count as f64).sqrt() * 1.5;
        score += base_penalty + progress_ramp + density_incentive;
    } else {
        // Tightened Best-Fit: emphasize minimizing post_residual with higher non-linear power.
        score += (post_residual as f64).powf(1.82);

        // Advanced Lookahead: reward fitting the next item while minimizing wasted space.
        // Penalty reduction is dampened by progress to prioritize late-stream consolidation.
        if next_item_size > 0 && next_item_size <= post_residual {
            let lookahead_reward = 4.2 - (progress * 1.2);
            score -= (next_item_size as f64) * lookahead_reward;
        }

        // Criticality: If the item only fits in this bin, lock it in.
        if fitting_bins_count == 1 {
            score -= 64.0;
        }

        // Balancing: Penalize divergence from the mean to ensure uniform bin levels,
        // but prioritize small residuals (high fill_ratio) for the penalty calculation.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * (0.35 + fill_ratio * 0.65);
    }

    // Global pressure: Exponential penalty for open_bins_count to enforce high-density packing.
    // Transition point shifted to 9 to better match stream dynamics.
    let global_pressure = if open_bins_count > 9 {
        (open_bins_count as f64).powf(1.4) * 0.35
    } else {
        (open_bins_count as f64) * 0.15
    };

    score += global_pressure;

    // Final adjustment: Penalize bins that create "unfillable" gaps (too small for most future items).
    // If post_residual is < 15 and we are in the mid-stream, add a small penalty to force 
    // usage of larger residual bins first.
    if post_residual > 0 && post_residual < 15 && progress > 0.2 && progress < 0.8 {
        score += 8.0 * (1.0 - progress);
    }

    score
}
